using Microsoft.AspNetCore.Mvc; using Prueba.DTOs; using Prueba.Services; namespace Prueba.Controllers;
[ApiController, Route("api/clientes")] public class ClientesController(IClienteService s) : ControllerBase { [HttpGet] public async Task<ActionResult<IReadOnlyCollection<ClienteDto>>> GetAll(CancellationToken ct) => Ok(await s.GetAllAsync(ct)); [HttpPost] public async Task<ActionResult<ClienteDto>> Create(CrearClienteDto r, CancellationToken ct) { var x = await s.CreateAsync(r, ct); return x.Success ? Created($"/api/clientes/{x.Value!.Id}", x.Value) : Problem(x.Error, statusCode: x.StatusCode); } }
